+    /// <summary>
+    /// Verifies that a closed generic value type from a referenced (metadata) assembly does not crash the analyzer.
+    /// </summary>
+    /// <see href="https://github.com/MessagePack-CSharp/MessagePack-CSharp/issues/2283" />
+    [Theory]
+    [InlineData("public partial record struct Item<T>([property: Key(0)] string Key);")]
+    [InlineData("public struct Item<T> { [Key(0)] public string Key { get; set; } }")]
+    public async Task ClosedGenericValueTypeFromReferencedAssembly(string itemDeclaration)
+    {
+        string libSource = Preamble + @"
+namespace Lib;
+
+[MessagePackObject]
+" + itemDeclaration;
+
+        string input = Preamble + @"
+using Lib;
+
+[MessagePackObject]
+public sealed partial record Cmd([property: Key(0)] string Scope)
+{
+    [Key(1)] public Item<int> Member { get; init; }
+}
+";
+
+        VerifyCS.Test test = new()
+        {
+            TestCode = input,
+        };
+
+        // Compile the library to an actual metadata reference so that its symbols have no syntax.
+        System.Collections.Immutable.ImmutableArray<Microsoft.CodeAnalysis.MetadataReference> frameworkReferences =
+            await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(Microsoft.CodeAnalysis.LanguageNames.CSharp, CancellationToken.None);
+        CSharpCompilation libCompilation = CSharpCompilation.Create(
+            "Lib",
+            new[] { CSharpSyntaxTree.ParseText(libSource, new CSharpParseOptions(LanguageVersion.CSharp10)) },
+            frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
+            new CSharpCompilationOptions(Microsoft.CodeAnalysis.OutputKind.DynamicallyLinkedLibrary));
+        using MemoryStream libImage = new();
+        Microsoft.CodeAnalysis.Emit.EmitResult emitResult = libCompilation.Emit(libImage);
+        Assert.True(emitResult.Success, string.Join(Environment.NewLine, emitResult.Diagnostics));
+        test.TestState.AdditionalReferences.Add(Microsoft.CodeAnalysis.MetadataReference.CreateFromImage(libImage.ToArray()));
+
+        await test.RunAsync();
+    }
+
